// build/wf/copy-as-python/javascript.ts
function run(parsed, sdk) {
  const parsedString = sdk.asString(parsed);
  const lines = parsedString.split(/\r?\n/);
  const [requestType, pathWithQuery] = lines[0]?.split(" ") ?? [];
  const [path, queryString] = pathWithQuery?.split("?") ?? [];
  const hostHeaderLine = lines.find((line) => line.startsWith("Host:"));
  if (!hostHeaderLine) {
    sdk.console.error("Host header not found");
    return "";
  }
  const host = hostHeaderLine.split(" ")[1]?.trim() ?? "";
  const headers = {};
  let contentStartIndex = -1;
  for (let i = 1; i < lines.length; i++) {
    const line = lines[i];
    if (line === "") {
      contentStartIndex = i + 1;
      break;
    }
    const [key, ...valueParts] = line?.split(": ") ?? [];
    if (key) {
      headers[key] = valueParts.join(": ").trim();
    }
  }
  const content = lines.slice(contentStartIndex).join("\n").trim();
  let completeURL = `https://${host}${path}`;
  if (queryString) {
    completeURL += `?${queryString}`;
  }
  let pythonCode = `import requests

`;
  pythonCode += `url = "${completeURL}"
`;
  let headersStr = "";
  for (const [key, value] of Object.entries(headers)) {
    headersStr += `    '${key}': '${value.replace(/'/g, "\\'")}',
`;
  }
  pythonCode += `headers = {
${headersStr}}
`;
  function replaceBooleanStrings(input) {
    return input.replace(/\btrue\b/g, "True").replace(/\bfalse\b/g, "False");
  }
  let payload = "";
  let payloadKey = "";
  if (requestType !== "GET") {
    if (content.trim().startsWith("{") && content.trim().endsWith("}")) {
      try {
        const requestData = JSON.parse(content);
        payload = `${replaceBooleanStrings(JSON.stringify(requestData, null, 2))}
`;
        payloadKey = "json";
      } catch (error) {
        sdk.console.error("Error parsing JSON: " + JSON.stringify(error));
        payload = `'''${content.replace(/'/g, "\\'")}'''
`;
        payloadKey = "data";
      }
    } else if (content.includes("=")) {
      const formData = parseFormData(content);
      payload = `${replaceBooleanStrings(JSON.stringify(formData, null, 2))}
`;
      payloadKey = "data";
    } else {
      payload = `'''${replaceBooleanStrings(content.replace(/'/g, "\\'"))}'''
`;
      payloadKey = "data";
    }
  }
  function parseFormData(formDataString) {
    const formData = {};
    const formEntries = formDataString.split("&");
    for (const entry of formEntries) {
      const [key, value] = entry.split("=");
      if (key && value) {
        formData[decodeURIComponent(key)] = decodeURIComponent(value);
      }
    }
    return formData;
  }
  if (requestType === "GET") {
    pythonCode += `response = requests.get(url, headers=headers)
`;
  } else if (requestType === "PUT" || requestType === "DELETE") {
    if (payload) {
      pythonCode += `${payloadKey} = ${payload}
`;
      pythonCode += `response = requests.${requestType.toLowerCase()}(url, headers=headers, ${payloadKey}=${payloadKey})
`;
    } else {
      pythonCode += `response = requests.${requestType.toLowerCase()}(url, headers=headers)
`;
    }
  } else {
    if (payload) {
      pythonCode += `${payloadKey} = ${payload}
`;
      pythonCode += `response = requests.${requestType?.toLowerCase() ?? ""}(url, headers=headers, ${payloadKey}=${payloadKey})
`;
    } else {
      pythonCode += `response = requests.${requestType?.toLowerCase() ?? ""}(url, headers=headers)
`;
    }
  }
  return pythonCode;
}
